#include <iostream>

class Money {
public:
    explicit Money(long long cents = 0) : cents_{cents} {}

    Money& operator+=(const Money& rhs) { cents_ += rhs.cents_; return *this; }
    Money& operator-=(const Money& rhs) { cents_ -= rhs.cents_; return *this; }

    long long cents() const { return cents_; }

private:
    long long cents_;
};

Money operator+(const Money& a, const Money& b) { Money r{a}; r += b; return r; }
Money operator-(const Money& a, const Money& b) { Money r{a}; r -= b; return r; }

bool operator==(const Money& a, const Money& b) { return a.cents() == b.cents(); }
bool operator!=(const Money& a, const Money& b) { return !(a == b); }
bool operator<(const Money& a, const Money& b)  { return a.cents() < b.cents(); }

std::ostream& operator<<(std::ostream& os, const Money& m) {
    long long c = m.cents();
    long long a = c < 0 ? -c : c;
    os << (c < 0 ? "-" : "") << a / 100 << '.'
       << (a % 100 < 10 ? "0" : "") << a % 100;
    return os;
}

int main() {
    Money buy{421700};      // 4217.00
    Money sell{423125};     // 4231.25
    Money pnl = sell - buy;
    std::cout << pnl << '\n';             // 14.25
    pnl += Money{-300};                   // a 3.00 commission
    std::cout << pnl << '\n';             // 11.25
    std::cout << (buy < sell) << '\n';    // 1
}

#include <iostream>

