guidedExercise.solution:
-8 x 250 = -2000 cents prints as `-20.00`; applying unary minus gives `Money{2000}`, printed as `20.00`.

```cpp
#include <iostream>

class Money {
public:
    explicit Money(long long cents = 0) : cents_{cents} {}
    Money operator-() const { return Money{-cents_}; }                 // unary
    Money operator*(long long n) const { return Money{cents_ * n}; }   // scale
    long long cents() const { return cents_; }
private:
    long long cents_;
};

std::ostream& operator<<(std::ostream& os, const Money& m) {
    long long c = m.cents();
    long long a = c < 0 ? -c : c;
    os << (c < 0 ? "-" : "") << a / 100 << '.'
       << (a % 100 < 10 ? "0" : "") << a % 100;
    return os;
}

int main() {
    Money perLot{-8};
    Money total = perLot * 250;   // -2000 cents
    std::cout << total << '\n';   // -20.00
    std::cout << -total << '\n';  // 20.00
}
```

independentExercise.solution:
The notionals are 304.5, 420.0 and 500.0, so the smallest is 304.5.

```cpp
#include <algorithm>
#include <iostream>
#include <vector>

class Order {
public:
    Order(int qty, double limitPx) : qty_{qty}, limitPx_{limitPx} {}
    double notional() const { return qty_ * limitPx_; }
private:
    int qty_;
    double limitPx_;
};

bool operator<(const Order& a, const Order& b) { return a.notional() < b.notional(); }

int main() {
    std::vector<Order> book{{3, 101.5}, {10, 42.0}, {2, 250.0}};
    std::sort(book.begin(), book.end());
    std::cout << book.front().notional() << '\n';   // 304.5
}
```

As a member, `a < b` still works for Order-on-the-left comparisons; the free form additionally supports symmetric conversions if Order ever gains non-explicit converting constructors. With a non-converting class like this one, both placements behave identically.

